public static TResult Combine<T,TResult>(
    IEnumerable<T> source, Func<TResult> seed,
    Func<TResult,T,TResult> accumulator) where TResult : notnull
{
    var acc = seed();
    foreach (var item in source) acc = accumulator(acc, item);
    return acc;
}

public async IAsyncEnumerable<Record> StreamRecordsAsync(
    string query, [EnumeratorCancellation] CancellationToken ct = default)
{
    await using var conn   = await _db.OpenAsync(ct);
    await using var cmd    = conn.CreateCommand(query);
    await using var reader = await cmd.ExecuteReaderAsync(ct);
    while (await reader.ReadAsync(ct))
    { ct.ThrowIfCancellationRequested(); yield return MapRow(reader); }
}

public async Task<OperationResult<T>> ExecuteWithRetryAsync<T>(
    Func<CancellationToken,Task<T>> operation, int maxRetries, CancellationToken ct)
{
    var attempt = 0;
    while (attempt < maxRetries)
    {
        try { var r = await operation(ct); return OperationResult<T>.Ok(r); }
        catch (TransientException) when (attempt < maxRetries-1)
        { attempt++; await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2,attempt)),ct); }
    }
    return OperationResult<T>.Fail("Max retries exceeded");
}

